'use strict';
// Firma y sello extraidos del PDF proporcionado por la titular.
const defaultSignature='data:image/png;base64,';
const $=s=>document.querySelector(s), key='emilce-abente-recibos-v1';
const defaults=()=>({version:1,clients:[],receipts:[],settings:{professional:'Abogada Emilce Abente',phone:'+595981486707',address:'Luis Brizuela c/ Ruta D025',contactRevision:1,city:'Asunción',paper:'80'}});
let db=defaults(),saved=null,storageOK=true;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const money=n=>new Intl.NumberFormat('es-PY').format(n)+' Gs.';
const number=n=>String(n).padStart(6,'0');
const dateText=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)?s.split('-').reverse().join('/'):'—';
const text=(s,max)=>typeof s==='string'&&s.length<=max;
function validClient(c){return c&&text(c.id,100)&&c.id&&text(c.name,160)&&c.name.trim()&&text(c.document,60)&&text(c.phone,60)&&text(c.address,250);}
function validSettings(s){return s&&text(s.professional,120)&&s.professional.trim()&&text(s.phone,60)&&(s.address===undefined||text(s.address,250))&&text(s.city,100)&&s.city.trim()&&['58','80'].includes(s.paper);}
function validDB(d){return d&&d.version===1&&validSettings(d.settings)&&Array.isArray(d.clients)&&Array.isArray(d.receipts)&&d.clients.every(validClient)&&new Set(d.clients.map(c=>c.id)).size===d.clients.length&&new Set(d.receipts.map(r=>r.number)).size===d.receipts.length&&d.receipts.every(r=>r&&Number.isSafeInteger(r.number)&&r.number>0&&validClient(r.client)&&validSettings(r.office)&&text(r.date,10)&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&!isNaN(Date.parse(r.date))&&text(r.city,100)&&r.city.trim()&&text(r.concept,1000)&&r.concept.trim()&&Number.isSafeInteger(r.amount)&&r.amount>0&&r.amount<=999999999999&&text(r.method,60)&&text(r.notes,1000));}
function migrateContact(data){if(data.settings.contactRevision!==1){data.settings.phone='+595981486707';data.settings.address='Luis Brizuela c/ Ruta D025';data.settings.contactRevision=1;}return data;}
function notice(msg){$('#notice').textContent=msg;$('#notice').hidden=false;}
try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(!validDB(parsed))throw Error();db=migrateContact(parsed);}localStorage.setItem(key,JSON.stringify(db));}catch(e){storageOK=false;}
function commit(next){next=migrateContact(next);if(!storageOK){notice('No se puede guardar: revisá el almacenamiento del navegador o restaurá un respaldo válido desde Configuración.');return false;}try{localStorage.setItem(key,JSON.stringify(next));db=next;return true;}catch(e){notice('No se pudo guardar. El almacenamiento está lleno o bloqueado. Descargá un respaldo antes de continuar.');return false;}}
function latest(){try{const raw=localStorage.getItem(key);if(raw){const fresh=JSON.parse(raw);if(!validDB(fresh))throw Error();db=migrateContact(fresh);}return true;}catch(e){notice('No se pudieron leer los datos guardados. Recargá la página antes de continuar.');return false;}}
function nextNumber(){return db.receipts.reduce((n,r)=>Math.max(n,r.number),0)+1;}
function draft(){return {number:nextNumber(),client:db.clients.find(c=>c.id===$('#client-select').value)||{name:'Nombre del cliente',document:''},date:$('#date').value,city:$('#city').value,concept:$('#concept').value||'Concepto del pago',amount:Number($('#amount').value)||0,method:$('#method').value,notes:$('#notes').value,office:{...db.settings}};}
function receiptHTML(r,preview=false){return `<div class="receipt-head"><strong>${esc(r.office.professional)}</strong><small>ESTUDIO JURÍDICO</small>${r.office.phone?`<div>Tel. ${esc(r.office.phone)}</div>`:''}${r.office.address?`<div>${esc(r.office.address)}</div>`:''}</div><hr><h3>RECIBO DE PAGO</h3><div class="center">N.º ${number(r.number)}${preview?' · BORRADOR':''}</div><hr><div class="row"><span>Fecha</span><b>${dateText(r.date)}</b></div><div class="row"><span>Ciudad</span><b>${esc(r.city)||'—'}</b></div><hr><div>Recibí de:</div><b>${esc(r.client.name)}</b>${r.client.document?`<div>CI / RUC: ${esc(r.client.document)}</div>`:''}<div style="margin-top:14px">En concepto de:</div><div class="text">${esc(r.concept)}</div><hr><div class="row total"><span>TOTAL</span><span>${money(r.amount)}</span></div><div class="row"><span>Forma de pago</span><span>${esc(r.method)}</span></div>${r.notes?`<hr><div>Observaciones:</div><div class="text">${esc(r.notes)}</div>`:''}<div class="signature"><img class="signature-image" src="${defaultSignature}" alt="Firma y sello de Emilce Diana Abente"><div class="signature-label">Firma y aclaración</div></div><div class="center muted">Gracias por su confianza.</div>`;}
function preview(){const r=saved||draft();$('#receipt-preview').innerHTML=receiptHTML(r,!saved);$('#next-number').textContent=(saved?'Guardado · ':'N.º ')+number(r.number);$('#paper-label').textContent=`PAPEL ${db.settings.paper} MM`;$('#receipt-preview').style.width=db.settings.paper==='58'?'219px':'302px';}
function clientsOptions(){const id=$('#client-select').value;$('#client-select').innerHTML='<option value="">Elegí un cliente</option>'+[...db.clients].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}${c.document?' · '+esc(c.document):''}</option>`).join('');$('#client-select').value=id;}
const titles={new:['Nuevo recibo','Registrá un pago y entregá un comprobante a tu cliente.'],history:['Historial de recibos','Consultá los pagos registrados y volvé a imprimir sus comprobantes.'],clients:['Clientes','La información de tus clientes, en un solo lugar.'],settings:['Configuración','Personalizá los recibos y administrá tus copias de respaldo.']};
function navigate(view){document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!=='view-'+view);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-title').textContent=titles[view][0];$('#page-description').textContent=titles[view][1];renderLists();if(view==='settings'){const s=db.settings;$('#professional').value=s.professional;$('#office-phone').value=s.phone;$('#office-address').value=s.address||'';$('#default-city').value=s.city;$('#paper').value=s.paper;}}
document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)navigate(b.dataset.view);});
function renderLists(){const q=$('#receipt-search').value.toLocaleLowerCase();const list=[...db.receipts].reverse().filter(r=>[r.client.name,r.client.document,r.concept,number(r.number)].join(' ').toLocaleLowerCase().includes(q));$('#receipt-list').innerHTML=list.length?list.map(r=>`<div class="list-row"><div><strong>N.º ${number(r.number)} · ${esc(r.client.name)}</strong><p>${dateText(r.date)} · ${esc(r.city)} · ${esc(r.method)}</p><p>${esc(r.concept)}</p></div><div class="row-actions"><b>${money(r.amount)}</b><button class="secondary" data-print="${r.number}">Imprimir</button></div></div>`).join(''):`<div class="empty">${db.receipts.length?'No se encontraron recibos.':'Todavía no hay recibos.<br>Registrá tu primer pago en «Nuevo recibo».'}</div>`;const cq=$('#client-search').value.toLocaleLowerCase();const clients=[...db.clients].sort((a,b)=>a.name.localeCompare(b.name)).filter(c=>(c.name+' '+c.document).toLocaleLowerCase().includes(cq));$('#client-list').innerHTML=clients.length?clients.map(c=>`<div class="list-row"><div><strong>${esc(c.name)}</strong><p>${esc(c.document)||'Sin documento'}${c.phone?' · '+esc(c.phone):''}</p>${c.address?`<p>${esc(c.address)}</p>`:''}</div><button class="secondary" data-edit="${esc(c.id)}">Editar</button></div>`).join(''):`<div class="empty">${db.clients.length?'No se encontraron clientes.':'Tu agenda está lista.<br>Agregá un cliente para comenzar a emitir recibos.'}</div>`;}
function openClient(id){const c=db.clients.find(c=>c.id===id)||{id:'',name:'',document:'',phone:'',address:''};$('#client-dialog-title').textContent=c.id?'Editar cliente':'Nuevo cliente';for(const k of ['id','name','document','phone','address'])$('#client-'+k).value=c[k];$('#client-dialog').showModal();}
$('#add-client').onclick=()=>openClient();$('#new-client').onclick=()=>openClient();$('#close-dialog').onclick=()=>$('#client-dialog').close();
$('#client-form').onsubmit=e=>{e.preventDefault();if(!latest())return;const c={};for(const k of ['id','name','document','phone','address'])c[k]=$('#client-'+k).value.trim();if(!c.name)return;const duplicate=db.clients.find(x=>x.document&&c.document&&x.document.toLowerCase()===c.document.toLowerCase()&&x.id!==c.id);if(duplicate){alert('Ya existe un cliente con ese documento: '+duplicate.name);return;}c.id=c.id||crypto.randomUUID();const next=structuredClone(db),i=next.clients.findIndex(x=>x.id===c.id);if(i<0)next.clients.push(c);else next.clients[i]=c;if(commit(next)){$('#client-dialog').close();clientsOptions();$('#client-select').value=c.id;renderLists();preview();notice('Cliente guardado correctamente.');}};
$('#receipt-form').addEventListener('input',preview);
function lockReceipt(value){$('#receipt-form').querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=value);$('#saved-actions').hidden=!value;}
$('#receipt-form').onsubmit=async e=>{e.preventDefault();if(saved)return;const save=()=>{if(!latest())return;const r=draft();if(!db.clients.some(c=>c.id===r.client.id)||!r.city.trim()||!r.concept.trim()){notice('Completá el cliente, la ciudad y el concepto.');return;}r.city=r.city.trim();r.concept=r.concept.trim();const next=structuredClone(db);next.receipts.push(r);if(!validDB(next)){notice('Revisá el importe, la fecha y los datos ingresados.');return;}if(commit(next)){saved=structuredClone(r);lockReceipt(true);preview();renderLists();notice(`Recibo N.º ${number(r.number)} guardado. Ya podés imprimirlo.`);}};if(navigator.locks)await navigator.locks.request(key,save);else save();};
function resetForm(){saved=null;lockReceipt(false);$('#receipt-form').reset();$('#date').value=today();$('#city').value=db.settings.city;preview();}
$('#receipt-form').addEventListener('reset',()=>setTimeout(()=>{$('#date').value=today();$('#city').value=db.settings.city;preview();},0));
$('#another').onclick=resetForm;
async function printReceipt(r){$('#print-area').innerHTML=`<article class="receipt">${receiptHTML(r)}</article>`;document.documentElement.style.setProperty('--receipt-width',db.settings.paper==='58'?'50mm':'72mm');let style=$('#print-page-style');if(!style){style=document.createElement('style');style.id='print-page-style';document.head.appendChild(style);}style.textContent=`@page {size: auto; margin: 0;}`;try{await Promise.all(Array.from($('#print-area').querySelectorAll('img'),img=>img.decode()));window.print();}catch(error){notice('No se pudo cargar la firma. Vuelve a intentar imprimir el recibo.');}}
$('#print-saved').onclick=()=>{if(saved)printReceipt(saved);};$('#receipt-list').onclick=e=>{const b=e.target.closest('[data-print]');if(b){const r=db.receipts.find(r=>r.number===Number(b.dataset.print));if(r)printReceipt(r);}};$('#client-list').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)openClient(b.dataset.edit);};
$('#receipt-search').oninput=renderLists;$('#client-search').oninput=renderLists;
$('#settings-form').onsubmit=e=>{e.preventDefault();if(!latest())return;const next=structuredClone(db);next.settings={professional:$('#professional').value.trim(),phone:$('#office-phone').value.trim(),address:$('#office-address').value.trim(),contactRevision:1,city:$('#default-city').value.trim(),paper:$('#paper').value};if(!validSettings(next.settings)){notice('Completá el nombre profesional y la ciudad.');return;}if(commit(next)){if(!saved)$('#city').value=db.settings.city;preview();notice('Configuración guardada.');}};
function downloadBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`respaldo-emilce-abente-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#backup').onclick=()=>{if(storageOK)latest();downloadBackup();};
$('#restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error();const data=JSON.parse(await file.text());if(!validDB(data))throw Error();if(!confirm(`El respaldo contiene ${data.clients.length} clientes y ${data.receipts.length} recibos. Reemplazará todos los datos actuales. ¿Continuar?`))return;if(storageOK)downloadBackup();const wasOK=storageOK;storageOK=true;if(commit(data)){clientsOptions();resetForm();navigate('settings');notice('Respaldo restaurado correctamente.');}else storageOK=wasOK;}catch(err){notice('El archivo no es un respaldo válido de esta aplicación. No se modificaron tus datos.');}finally{e.target.value='';}};
window.addEventListener('storage',e=>{if(e.key===key&&latest()){clientsOptions();renderLists();preview();}});
$('#today-label').textContent=new Intl.DateTimeFormat('es-PY',{day:'numeric',month:'long',year:'numeric'}).format(new Date());clientsOptions();resetForm();renderLists();if(!storageOK)notice('El almacenamiento local no está disponible o contiene datos dañados. No se sobrescribieron los datos. Revisá el navegador o restaurá una copia válida desde Configuración.');
